RecursionError.correct_example:
def factorial(n):
    if n <= 1:      # базовый случай
        return 1
    return n * factorial(n - 1)

print(factorial(5))  # 120

NotImplementedError.correct_example:
class Animal:
    def speak(self):
        raise NotImplementedError('Переопределите speak()')

class Dog(Animal):
    def speak(self):
        return 'Гав!'

dog = Dog()
print(dog.speak())

